const int R = 25, G = 26, B = 27;
int cycles = 0;

void setup() {
  Serial.begin(115200);
  pinMode(R, OUTPUT); pinMode(G, OUTPUT); pinMode(B, OUTPUT);
}

void show(int r, int g, int b) {
  digitalWrite(R, r); digitalWrite(G, g); digitalWrite(B, b);
  delay(300);
}

void loop() {
  show(HIGH, LOW, LOW);
  show(LOW, HIGH, LOW);
  show(LOW, LOW, HIGH);
  if (++cycles == 1) Serial.println("RGB");
}
